# The Professional Kitchen (cupro): lessons. Career figures: BLS OOH (page modified Aug 27, 2026). Michelin's own words.
LESSONS = {
"brigade": LES([
 P("In the late 1800s, at grand hotels such as the Savoy and the Carlton in London, Auguste Escoffier organized big kitchens like a well-run team. Each group of cooks had one job and one leader. His system, the <b>brigade de cuisine</b>, still shapes kitchen titles today."),
 K("<b>Chef de cuisine</b> (head chef) runs the kitchen; the <b>sous-chef</b> (\"under-chef\") is second in command and runs service. <b>Chefs de partie</b> (station chefs) each lead a station, helped by cooks and <b>commis</b> (junior cooks). <b>Plongeurs</b> wash dishes; the <b>aboyeur</b> (\"barker\") calls orders. Most kitchens today combine stations, but the titles live on."),
 V("cu-brigade", None, "Click a role to see what that person does."),
 TB(["Station chef", "Job"], [["Saucier", "Sauces and sautéed dishes; often the most senior station"], ["Poissonnier", "Fish"], ["Rôtisseur", "Roasts and their jus"], ["Grillardin", "Grilled foods"], ["Friturier", "Fried foods"], ["Entremetier", "Vegetables, starches, soups and eggs (sometimes split into potager and legumier)"], ["Garde manger", "Cold foods: salads, cold appetizers, pâtés"], ["Pâtissier", "Pastry and desserts"], ["Boucher", "Butchery"], ["Tournant", "Fills in at any station"]]),
 W("The brigade divides a huge menu into parts that one person can master, and makes it clear who answers to whom when service gets hectic."),
 EX("Who?", "Who makes the béarnaise and the pan sauces in a classical brigade?", ["Sauces and sautés belong to one station."], "The saucier."),
 M("Thinking every restaurant has every station. A small kitchen might have a chef, a sous-chef and three cooks covering everything."),
 DRILL("Write the brigade for your home kitchen on a holiday: who is chef, who is garde manger, who is plongeur?"),
 MP([("classics/", "From the Great Kitchens", "Escoffier's recipes from the Savoy and the Carlton")]),
 TRY,
], "w_brigade", "g_escoffier", "escoffier"),

"kitchen-language": LES([
 P("Kitchens are loud, crowded and full of hot things and knives. Cooks use short calls so everyone knows where everyone is and what is happening."),
 K("<b>Safety calls:</b> \"<b>Behind</b>\" (I'm passing behind you), \"<b>Corner</b>\" (I'm coming around a blind corner), \"<b>Hot</b>\" (I'm carrying something hot), \"<b>Sharp</b>\" or \"<b>Knife</b>\" (I'm carrying a knife), \"<b>Open door</b>\" (oven door open). <b>Service calls:</b> \"<b>Heard</b>\" (I understand), \"<b>Ordering</b>\" (get ready), \"<b>Fire</b>\" (start cooking), \"<b>All day</b>\" (total of one item), \"<b>86</b>\" (we're out of it), \"<b>On the fly</b>\" (needed right away), \"<b>Walking in</b>\" (on its way), \"<b>In the weeds</b>\" (overwhelmed)."),
 W("A cook turning around with a pan of hot oil can't see you behind them. One word prevents an accident. Answering \"heard\" tells the chef the order was received, so nothing is lost in the noise."),
 EX("What do you say?", "You're carrying a hot sheet pan past a cook at the stove.", ["Two warnings: where you are, and that it's hot."], "\"Hot behind!\""),
 M("Walking silently behind someone in a kitchen."),
 DRILL("For one week, use \"behind\", \"hot\" and \"heard\" at home whenever you cook with someone else. It becomes a habit fast."),
 TRY,
], "cia"),

"station-prep": LES([
 P("Before service, every cook preps a station so that during service they never have to leave it."),
 K("A <b>par level</b> is the amount of an item you need on hand for a service (or a day). The <b>prep list</b> is what to make: <b>par − on hand</b>. A <b>station setup</b> (often from a diagram) puts every ingredient, tool and plate in reach, in the same place every day, with backups in the reach-in below."),
 LI("Count what's on hand first, then write the prep list.",
    "Do long or slow prep first; delicate items (herbs, some sauces) last.",
    "Set the station the same way every time so your hands know where things are.",
    "Label and date everything (Food Safety)."),
 W("Pars come from sales history: if Friday dinner sells about 60 risottos, you need enough parcooked rice for 60, plus a small buffer. Too little and you run out; too much and it's waste."),
 EX("Prep list", "Par for diced shallots is 2 quarts. You have 0.5 quart left from yesterday. How much do you prep?", ["$2 - 0.5 = 1.5$."], "1½ quarts."),
 M("Prepping by habit, not by par. You end up short of one thing and throwing out another."),
 DRILL("Before cooking dinner for a week, write a par sheet for your home \"station\": how much of each staple you need, how much you have, and what to prep."),
 TRY,
], "cia"),

"ordering-inventory": LES([
 P("Food is a restaurant's biggest daily cost after labor. Ordering, receiving and counting it well saves money and keeps food safe."),
 K("<b>Order</b> from pars and the coming week's bookings. <b>Receive</b> carefully: check cold food arrives at 41°F or below and frozen food frozen solid, check quality and count against the invoice, reject what's wrong, and put food away fast (cold first). <b>Rotate</b> first in, first out. <b>Count inventory</b> on a schedule (often weekly or monthly) to work out what was used."),
 LI("Reject deliveries with signs of temperature abuse: thawed and refrozen food, large ice crystals, warm cold food.",
    "Check packaging is intact and shellfish has its tags.",
    "Store new deliveries behind or under the old.",
    "Food used = opening inventory + purchases − closing inventory."),
 W("The inventory formula tells the kitchen how much food it actually used, which, compared with sales, shows waste, theft or portion drift."),
 EX("Food used", "Opening inventory \\$8,000, purchases \\$5,500, closing inventory \\$7,200. What was the cost of food used?", ["$8000 + 5500 - 7200 = 6300$."], "\\$6,300."),
 M("Signing for a delivery without checking temperatures and counts."),
 DRILL("Do a full inventory of your pantry and refrigerator, then repeat it in a week. Using the formula and your grocery receipts, what did your household use?"),
 MP([("kitchen/know-how/#pantry", "Pantry staples and how long they keep", "")]),
 TRY,
], "foodcode", "cia"),

"recipe-costing": LES([
 P("To price a dish fairly you must know exactly what it costs, down to the pinch of salt and the trim you throw away."),
 K("<b>Yield percent</b> = usable weight ÷ purchased weight. <b>Usable (edible-portion) cost</b> per pound = purchase price per pound ÷ yield. <b>Recipe cost</b> = the sum of each ingredient's usable cost × amount. <b>Portion cost</b> = recipe cost ÷ portions. <b>Food-cost percent</b> = portion cost ÷ menu price."),
 V("cu-cost", {"mode": "recipe"}, "Change prices, yields and amounts: the recipe cost, the portion cost and the food-cost percent update."),
 W("A <b>yield test</b> is how kitchens find yields: weigh the item as bought, trim and prep it, and weigh what's usable. Whole salmon may give under half its weight as skinless fillet; carrots perhaps four-fifths after peeling and trimming. Costing from the purchase price alone makes a dish look cheaper than it is."),
 EX("Usable cost", "Whole beef tenderloin costs \\$18.00 per pound; trimmed, it yields 70%. What is the usable cost per pound?", ["$18.00 \\div 0.70 \\approx 25.71$."], "About \\$25.71 per pound."),
 EX("Food-cost percent", "A dish's portion cost is \\$5.60 and it sells for \\$18.00. What is its food-cost percent?", ["$5.60 \\div 18.00 \\approx 0.311$."], "About 31%."),
 M("Forgetting small things: oil, butter, salt, garnish, bread. Many kitchens add a few percent for them (a \"Q-factor\")."),
 DRILL("Cost a dinner you make at home from your grocery receipt, including oil and spices. Work out the cost per portion.", "Do a yield test on a bunch of carrots or a pineapple: weigh, peel and trim, weigh again."),
 SCI([("/math/grade-6/percent-of-a-number/", "Finding a percent of a number", "the math behind food cost"), ("/math/grade-7/percent-change/", "Percent increase and decrease", "price changes")]),
 TRY,
], "cia"),

"timing-service": LES([
 P("A dinner for four with three courses needs a dozen things to finish at the right moments. Professionals plan it backward from the time food leaves the kitchen."),
 K("<b>Backward planning:</b> start with the time the food must be on the plate, subtract each item's cooking and resting time, and write the start time for each. <b>Ticket time</b> is how long from order to plate; kitchens know theirs for each dish. <b>Fire</b> the longest items first so everything finishes together; hold what holds well (braises, sauces) and cook what doesn't (sautés, fried food) at the last moment."),
 V("cu-plan", None, "Set the serving time and each item's minutes; the plan shows when to start each one."),
 W("Some foods wait well and some don't. A braise is better the next day; a soufflé falls in minutes; fries go limp in five. Good timing builds a menu where the last-minute work is small."),
 EX("Start time", "Dinner is at 7:00 p.m. The roast needs 90 minutes in the oven and 20 minutes to rest. When does it go in?", ["$90 + 20 = 110$ minutes before 7:00.", "7:00 minus 1 hour 50 minutes is 5:10."], "5:10 p.m."),
 M("Starting everything at once. Quick dishes are ready far too early and sit under a heat lamp."),
 DRILL("For your next big dinner, write a backward schedule on paper with start times. Afterward, note where you ran early or late."),
 TRY,
], "cia"),

"cleaning-maintenance": LES([
 P("Clean kitchens are safer and run better, and equipment lasts longer. Kitchens clean on three schedules."),
 K("<b>As you go:</b> wipe spills, clean boards and tools between tasks, keep the station clear. <b>Daily (closing):</b> clean and sanitize every food-contact surface, the range and flat-top, the fryer area, floors and drains; empty and clean the steam table; take out trash. <b>Periodic (deep clean):</b> on a written schedule, clean hoods and filters, walk-in shelves, ovens, ice machines, behind and under equipment. <b>How often</b> each machine is cleaned, descaled or serviced follows the <b>manufacturer's instructions and local codes</b>."),
 TB(["Equipment", "Typical care (follow the manual and local rules)"], [["Hood filters", "Removed and washed on a regular schedule; busy grills and fryers need it often"], ["Hood and duct system", "Professionally inspected and cleaned at the intervals the fire code sets for that kind of cooking"], ["Fryer", "Oil filtered and changed; the fryer boiled out with the cleaner and method the maker specifies"], ["Ice machine", "Cleaned and sanitized as the maker directs; ice is food"], ["Combi and steam ovens", "Descaled and cleaned as the maker directs, often with built-in programs"], ["Refrigeration", "Thermometers checked; door gaskets cleaned; coils kept clear"], ["Knives and slicers", "Slicers cleaned and sanitized after use with the power off, as the manual directs"]]),
 SAFE("Unplug or lock out equipment before cleaning it, as its manual and OSHA rules require.", "Let fryer oil and hot equipment cool before cleaning.", "Grease buildup in hoods and filters is a fire risk; keep them on schedule."),
 W("Cleaning schedules turn \"someone should\" into \"this person, this day\". A chart on the wall with initials and dates is how most kitchens make sure the hood filters actually get washed."),
 EX("Schedule", "Your fryer manual says to boil out the fryer every 2 weeks. The last time was March 4. When is the next?", ["2 weeks = 14 days after March 4."], "March 18."),
 M("Skipping the hood filters until they drip grease."),
 DRILL("Write a cleaning schedule for your kitchen: daily, weekly and monthly jobs, each with a name. Follow it for a month."),
 MP([("kitchen/cleaning/#routines", "Daily, weekly and monthly", "a home cleaning routine"), ("kitchen/cleaning/#oven", "The oven and stove", ""), ("kitchen/cleaning/#fridge", "The refrigerator", "")]),
 TRY,
], "osha", "foodcode"),

"working-safely": LES([
 P("Kitchen injuries are mostly cuts, burns, slips and strains. Nearly all of them are prevented by habits."),
 K("<b>Cuts:</b> sharp knives, the claw, a steady board, knives carried point down, never left in the sink, mandolines with guards. <b>Burns:</b> dry towels or mitts for hot handles (water carries heat through), handles turned in, open steamers and oven doors away from your face, no reaching over hot surfaces, oil cooled before moving. <b>Slips:</b> closed, non-slip shoes; spills cleaned at once; wet-floor signs; no running. <b>Strains:</b> lift with your legs, keep loads close, get help with heavy stockpots, use carts."),
 SAFE("OSHA's restaurant guide lists fryers as a leading cause of burns, and says to wear long sleeves and a proper apron, never pour water into hot oil, and use Class K extinguishers on grease fires.",
      "Keep fire exits and extinguishers clear, and know where the hood's manual pull station is.",
      "Pull plugs by the plug, not the cord; report frayed cords and broken equipment.",
      "Store heavy items on low shelves; use a step stool, not a crate, to reach high ones."),
 W("A wet towel grabbing a 400°F pan handle is one of the most common burns in kitchens. Water conducts heat far better than dry cloth and turns to steam."),
 EX("Safer choice", "A stockpot holds 5 gallons of hot stock. About how much does the stock weigh? (A gallon of water weighs about 8.3 pounds.)", ["$5 \\times 8.3 = 41.5$ pounds, plus the pot.", "Too much to carry alone, and it's hot: get help or ladle it out."], "About 41.5 pounds; get help or ladle it."),
 M("Using a wet towel for a hot handle."),
 DRILL("Look around your kitchen for the hazards in this lesson: wet towels near the stove, handles sticking out, knives in the sink, a slippery mat. Fix three of them."),
 TRY,
], "osha", "cfd"),

"michelin": LES([
 P("The Michelin Guide began in 1900 as a free booklet for French motorists from the Michelin tire company. Stars for restaurants came in the 1920s and 1930s. Today a Michelin star is one of the best-known honors a kitchen can earn."),
 K("In Michelin's own words, <b>one star</b>: \"worth a stop\"; <b>two stars</b>: \"worth a detour\"; <b>three stars</b>: \"worth a special journey\". Anonymous inspectors, who book under assumed names and pay their bills, judge the food on <b>five criteria</b>: the quality of the ingredients; the harmony of flavors; the mastery of techniques; the personality of the chef as expressed through the cuisine; and consistency across the menu and over time. The <b>Bib Gourmand</b> (since 1997) marks good quality and good value."),
 W("Look at what's on the list: ingredients, flavor, technique, a point of view, and consistency. Nothing about tablecloths. Michelin says the stars are for the food on the plate. Many other guides and awards rate restaurants too, by their own methods."),
 EX("What counts?", "Which is one of Michelin's five published criteria for stars: the décor of the dining room, or consistency across the menu and over time?", ["Michelin's criteria are about the food."], "Consistency across the menu and over time."),
 M("Thinking stars go to chefs. They go to restaurants, and can be lost if the cooking changes."),
 DRILL("Pick one dish you cook well and judge it by the five criteria. Which is your weakest? Cook it three times in a month, aiming to make it the same each time."),
 TRY,
], "michelin", "g_michelin"),

"careers": LES([
 P("Cooking is a trade learned mostly by doing. Here is what the U.S. Bureau of Labor Statistics says about chefs and head cooks, and how people usually get there."),
 K("<b>The BLS (Occupational Outlook Handbook, page modified August 27, 2026):</b> chefs and head cooks typically need a high school diploma and <b>5 years or more of work experience</b> in a related job; median pay was <b>\\$62,470</b> a year in May 2025; there were about <b>220,300</b> jobs in 2025, with employment projected to grow <b>7%</b> from 2025 to 2035. <b>Most learn through work experience</b>, often starting as line cooks; others train in culinary programs, apprenticeships (some registered with the U.S. Department of Labor) or the Armed Forces."),
 LI("<b>Staging:</b> a <b>stage</b> (stahzh) is a short, often unpaid, working trial or visit in a kitchen; the cook is a <b>stagiaire</b>. It's how cooks learn new kitchens and how chefs try out new hires. Labor laws on unpaid work apply, so ask how a kitchen handles it.",
    "<b>Food handler cards</b> are required in some states and cities; a manager may need a food protection manager certificate.",
    "<b>ACF certification</b> (American Culinary Federation) is optional and climbs from Certified Fundamentals Cook and Certified Culinarian through Certified Sous Chef, Chef de Cuisine and Executive Chef to Certified Master Chef, with a pastry track; higher levels require years of experience, set courses (such as food safety, nutrition and supervisory management) and written and practical exams.",
    "<b>Typical path:</b> dishwasher or prep cook → line cook → station chef or lead → sous-chef → chef de cuisine → executive chef. It takes years."),
 W("Kitchen work is physical: long shifts, nights, weekends and holidays, standing in heat. Many cooks love it for the teamwork, the craft and the pace. Trying it, through a stage or a part-time job, is the best way to find out."),
 EX("Years", "A cook spends 2 years as a prep cook, 3 as a line cook and 2 as a sous-chef. How many years before becoming a chef de cuisine?", ["$2 + 3 + 2 = 7$."], "7 years."),
 M("Thinking a culinary degree alone makes you a chef. The BLS lists years of kitchen experience as typical."),
 DRILL("Ask a local restaurant whether they take stagiaires or part-time prep help. Prepare by practicing your knife cuts and kitchen calls."),
 TRY,
], "bls", "acf", "cia"),

"capstone": LES([
 P("Put the whole ladder to work: plan, cost, prep and cook a <b>five-course tasting menu</b> for four to six people at home."),
 K("<b>The project:</b> (1) an amuse-bouche, (2) a cold or soup course, (3) a fish or vegetable course, (4) a meat course with a sauce from the mothers, (5) a plated dessert. Write the menu; cost it; write prep lists; set a backward schedule from service; set the table formally; cook, plate and serve; then write down what went well and what you would change."),
 TB(["When", "What to do"], [
   ["2 to 3 weeks before", "Write the menu; cook any new dish once as a test; cost it (Recipe Costing)"],
   ["1 week before", "Final menu and shopping list; place setting planned; plates and serving tools counted"],
   ["3 days before", "Shop for keeping items; make stocks; make ice cream or sorbet"],
   ["2 days before", "Make the mother sauce base; pastry dough; quick pickles; dessert components"],
   ["1 day before", "Shop for fish and delicate produce; braise if braising; prep vegetables (cut, blanch, shock); set the table"],
   ["Morning of", "Final prep; label everything; set stations: hot, cold, pastry; clean as you go"],
   ["2 hours before", "Roast or start long items by your backward schedule; chill white wine or drinks; final kitchen clean"],
   ["Service", "Fire course by course; taste every plate; wipe rims; send"],
   ["After", "Clean down; cool leftovers by the two-stage rule; write your notes"],
 ], "A timeline that starts three days ahead"),
 V("cu-plan", {"preset": "capstone"}, "A sample backward schedule for the last two hours. Change the times to fit your menu."),
 W("Restaurant kitchens can serve a tasting menu because almost everything is done before the first guest arrives. At home it's the same: if the last hour is mostly plating and searing, it will feel calm."),
 EX("Cost per guest", "Your menu costs \\$138 in ingredients for 6 guests. What is the cost per guest?", ["$138 \\div 6 = 23$."], "\\$23 per guest."),
 SAFE("Keep cold dishes at 41°F or below and hot dishes at 135°F or above while they wait; ask guests about allergies when you invite them."),
 M("Five new techniques on the night. Test every dish once before."),
 DRILL("Cook the capstone. Ask your guests to rate each course on the five Michelin criteria, and keep the cards."),
 TRY,
], "cia", "michelin", "foodcode"),
}
